#include<bits/stdc++.h>

using namespace std;

long long f(long long x,long long n,vector<long long> &rw){
  long long res=(x/n)*rw[n];
  long long rem=x%n;
  res+=rw[rem];
  return res;
}

int main(){
  long long n,m,k;
  string s;
  cin >> n >> m >> k >> s;

  vector<long long> rw(n+1,0);
  for(long long i=0;i<n;i++){
    rw[i+1]=rw[i];
    if(s[i]=='x'){rw[i+1]++;}
  }

  long long res=0;
  for(long long i=1;i<=n;i++){
    long long fbeg=f(i-1,n,rw);
    long long l=i,r=n*m;
    while(l<=r){
      long long te=(l+r)/2;
      if(f(te,n,rw)-fbeg<=k){l=te+1;}
      else{r=te-1;}
    }
    res=max(r-i+1,res);
  }
  cout << res << "\n";
  return 0;
}

import java.util.*

fun main() {
  val sc = Scanner(System.`in`)
  val N = sc.nextInt()
  val M = sc.nextInt()
  val K = sc.nextLong()
  val S = sc.next()

  val cumsum = IntArray(N + 1) // cumsum[i]: [0, i)の区間に含まれる'x'の個数
  val maxuse = IntArray(N + 1) // maxuse[i]: 'x'をi個まで'o'に変える時、先頭から'o'が最大何個連続するか
  for (i in 1..N) {
    cumsum[i] = cumsum[i - 1] + if (S[i - 1] == 'x') 1 else 0
    maxuse[cumsum[i]] = i
  }
  val xCount = cumsum[N] // Sに含まれる'x'の個数
  println((0 until N).map { l -> // lを左端として、右端をどこまで伸ばせるか
    val toRight = xCount - cumsum[l] // 右端まで行く為に変える'x'の個数
    if (toRight > K) maxuse[(K + cumsum[l]).toInt()] - l.toLong() // 右端に行けないなら、答えはmaxuseから求まる
    else {
      val repeat = (K - toRight) / xCount // 完全に覆えるSの個数
      N - l + Math.min(N * (M - 1L), N * repeat + maxuse[(K - toRight - xCount * repeat).toInt()])
    }
  }.max()!!)
}
